-- Status rows whose fact time was set in the past: the leak even a correct fact-time predicate admits.
-- snowflake dialect. Generated by tools/emit_sql.py; `make sql` regenerates.
SELECT
    e.entity_id,
    e.event_id,
    e.status,
    e.fact_time,
    e.arrival_time,
    e.arrival_days - e.fact_days AS backdate_span_days
FROM events AS e
WHERE e.event_type = 'status_change'
  AND e.status = 'risky'
  AND e.arrival_days - e.fact_days > 10
ORDER BY backdate_span_days DESC, e.event_id
